function appendDraftDeploymentInstructions(instructions, deployment) {
  if (deployment?.operationStatus !== "Draft") {
    return instructions;
  }
  return `${instructions}
Deployment '${deployment.name}' exists but is still in Draft state (OperationStatus: ${deployment.operationStatus}, ActivationStatus: ${deployment.activationStatus}). Draft deployments are created by deploy runs that did not complete successfully and cannot be activated. Fix the deploy run validation errors, rerun 'uip solution deploy run', then activate after 'uip solution deploy list' shows the deployment is no longer Draft.`;
}
async function isPipelineDeploymentNotFoundError(error) {
  if (!error || typeof error !== "object") {
    return false;
  }
  const response = error["response"];
  if (!response || typeof response !== "object") {
    return false;
  }
  const status = response.status;
  if (status !== 404) {
    return false;
  }
  const [bodyError, body] = await catchError2(response.clone().text());
  if (bodyError || !body) {
    return false;
  }
  return body.includes("PipelineDeploymentNotFound");
}
function interpretFailedDeployPoll(deployment) {
  if (!deployment) {
    return;
  }
  if (deployment.operationStatus === "Failed" || deployment.operationStatus === "FailedRollback") {
    return {
      kind: "DeployFailed",
      operationStatus: deployment.operationStatus
    };
  }
  if (deployment.operationStatus !== "Successful") {
    return;
  }
  switch (deployment.activationStatus) {
    case "Active":
      return { kind: "Active", instanceId: deployment.instanceId };
    case "NeedsSetupToActivate":
      return { kind: "NeedsSetupToActivate" };
    case "ReadyToActivate":
    case "Inactive":
      return { kind: "ReadyToActivate" };
    case "ActivationFailed":
      return { kind: "ActivationFailed" };
    default:
      return;
  }
}
function mapOperationStatusToPipelineStatus(operationStatus) {
  switch (operationStatus) {
    case "Successful":
      return "DeploymentSucceeded";
    case "Failed":
    case "FailedRollback":
    case "Draft":
      return "DeploymentFailed";
    default:
      return;
  }
}
function deploymentToTerminalPipelineResult(deployment) {
  const status = mapOperationStatusToPipelineStatus(deployment.operationStatus);
  if (!status) {
    return;
  }
  return {
    status,
    validationResult: { validationErrors: [], conflictErrors: [] },
    deploymentKey: deployment.installDeploymentKey ?? deployment.key,
    configurationKey: deployment.configurationKey,
    instanceId: deployment.instanceId
  };
}

// src/services/activation.ts
var TERMINAL_STATUSES2 = new Set([
  "SuccessfulActivate",
  "FailedActivate"
]);
async function activateDeployment(auth, deploymentName, options) {
  const api = new PipelinesApi(new Configuration({
    basePath: auth.basePath,
    accessToken: auth.accessToken
  }));
  const [stepsError, steps] = await catchError2(api.pipelinesGetPreActivateSteps({ deploymentName }));
  if (stepsError) {
    const { message, details } = await extractErrorDetails(stepsError);
    const deployment = await findDeploymentForError(auth, deploymentName);
    return {
      kind: "RequestFailed",
      phase: "preActivateSteps",
      message,
      details,
      deployment
    };
  }
  if (steps.steps.length > 0) {
    logger.info(`Pre-activate steps for ${deploymentName}:`);
    for (const step of steps.steps) {
      logger.info(`  [${step.serviceName}] ${step.step}: ${step.description}`);
    }
  }
  const [activateError, activateResult] = await catchError2(api.pipelinesActivate({ deploymentName }));
  if (activateError) {
    const { message, details } = await extractErrorDetails(activateError);
    const deployment = await findDeploymentForError(auth, deploymentName);
    return {
      kind: "RequestFailed",
      phase: "activate",
      message,
      details,
      deployment
    };
  }
  const instanceId = activateResult.instanceId;
  if (!instanceId) {
    return { kind: "NoInstance" };
  }
  const pollResult = await pollUntil({
    fn: () => api.pipelinesGetDeploymentInstanceStatus({
      instanceId
    }),
    until: (result) => TERMINAL_STATUSES2.has(result.status),
    getStatus: (result) => result.status,
    label: `activate ${deploymentName}`,
    logPrefix: "activate",
    timeoutMs: options.timeoutSeconds * 1000,
    intervalMs: options.pollIntervalMs,
    signal: options.signal ?? processContext.pollSignal
  });
  if (pollResult.outcome !== PollOutcome.Completed || !pollResult.data) {
    return { kind: "PollFailed", poll: pollResult };
  }
  const finalStatus = pollResult.data;
  if (finalStatus.status !== "SuccessfulActivate") {
    const errorMessage2 = coerceWorkflowErrorMessages(finalStatus.errorMessage).map((e) => e.errorMessage).join(", ") || "Unknown error";
    return {
      kind: "ActivationFailed",
      status: finalStatus.status,
      instanceId,
      errorMessage: errorMessage2
    };
  }
  return {
    kind: "Success",
    status: finalStatus.status,
    instanceId
  };
}

