async function getSolutionAuthContext(options) {
  const ctx = await getAuthContext({
    tenant: options.tenant,
    ensureTokenValidityMinutes: options.loginValidity ?? 10,
    envFilePath: options.envFilePath,
    requireOrganizationId: true,
    requireTenantName: true
  });
  const organizationId = ctx.organizationId;
  const tenantName = ctx.tenantName;
  const basePath = `${ctx.baseUrl}/${organizationId}/${tenantName}/automationsolutions_`;
  return {
    accessToken: ctx.accessToken,
    basePath,
    organizationId,
    tenantName
  };
}

// src/services/deploy-activate-service.ts
var fail = (reason, message, instructions, exitCode = 1) => ({
  ok: false,
  reason,
  message,
  instructions,
  exitCode
});
var AUTH_INSTRUCTIONS = "Run 'uip login' to refresh credentials, then retry activation. If the deployment is in a different tenant, switch with 'uip login tenant set <tenant>'.";
async function activateDeploymentAsync(deploymentName, options = {}) {
  const [authError, auth] = await catchError2(getSolutionAuthContext({
    tenant: options.tenant,
    loginValidity: options.loginValidity,
    envFilePath: options.envFilePath
  }));
  if (authError) {
    return fail("auth_failed", authError.message, AUTH_INSTRUCTIONS);
  }
  const result = await activateDeployment(auth, deploymentName, {
    timeoutSeconds: options.timeout ?? 360,
    pollIntervalMs: options.pollInterval ?? 5000,
    signal: options.signal
  });
  if (result.kind === "RequestFailed") {
    const fallback = result.phase === "preActivateSteps" ? `Check deployment name. Deploy first with: uip solution deploy run. Details: ${result.details}` : `Check deployment name matches an existing deployment. Details: ${result.details}`;
    return fail("request_failed", result.message, appendDraftDeploymentInstructions(fallback, result.deployment));
  }
  if (result.kind === "NoInstance") {
    return {
      ok: true,
      status: "Activation completed (no instance to poll)",
      deploymentName
    };
  }
  if (result.kind === "PollFailed") {
    const { reason, message, exitCode } = mapPollFailure(result.poll, "Activation");
    return fail(reason, message, "Activation may still be in progress.", exitCode);
  }
  if (result.kind === "ActivationFailed") {
    return fail("activation_failed", `Activation failed with status: ${result.status}`, result.errorMessage);
  }
  return {
    ok: true,
    status: result.status,
    deploymentName,
    instanceId: result.instanceId
  };
}

