async function readConfigFile(filePath) {
  const fs7 = getFileSystem();
  const resolvedPath = fs7.path.resolve(filePath);
  const [readError, rawContent] = await catchError2(fs7.readFile(resolvedPath, "utf-8"));
  if (readError || !rawContent) {
    return [
      readError ?? new Error(`Config file is empty: ${resolvedPath}`),
      null
    ];
  }
  const [parseError, config] = catchError2(() => JSON.parse(rawContent));
  if (parseError) {
    return [
      new Error(`Invalid JSON in config file: ${parseError.message}`),
      null
    ];
  }
  if (!config.resources || !Array.isArray(config.resources)) {
    return [
      new Error("Invalid config file: missing or invalid 'resources' array"),
      null
    ];
  }
  return [null, { config, resolvedPath }];
}
function findResource(config, identifier) {
  const nameMatches = config.resources.filter((r) => r.name === identifier);
  if (nameMatches.length === 1) {
    return { resource: nameMatches[0], error: null };
  }
  if (nameMatches.length > 1) {
    return { resource: null, error: "duplicate" };
  }
  const keyMatch = config.resources.find((r) => r.resourceKey === identifier);
  if (keyMatch) {
    return { resource: keyMatch, error: null };
  }
  return { resource: null, error: "not_found" };
}
function resourceErrorMessage(identifier, findResult, config) {
  if (findResult.error === "duplicate") {
    const dupes = config.resources.filter((r) => r.name === identifier).map((r) => `${r.resourceKey} (${r.kind})`).join(", ");
    return {
      Message: `Multiple resources named '${identifier}' found in config`,
      Instructions: `Use resourceKey instead to target a specific one: ${dupes}`
    };
  }
  const available = config.resources.map((r) => `${r.name} (${r.kind})`).join(", ");
  return {
    Message: `Resource '${identifier}' not found in config`,
    Instructions: `Available resources: ${available}`
  };
}
async function writeConfigFile(filePath, config) {
  const fs7 = getFileSystem();
  const [writeError] = await catchError2(fs7.writeFile(filePath, `${JSON.stringify(config, null, 2)}
`));
  return writeError;
}
var TOP_LEVEL_FIELDS = new Set(["conflictFixingAction"]);
function isTopLevelField(property) {
  return TOP_LEVEL_FIELDS.has(property);
}
function getAvailableProperties(resource) {
  const topLevel = [...TOP_LEVEL_FIELDS];
  const configKeys = Object.keys(resource.configuration ?? {});
  return [...topLevel, ...configKeys].join(", ");
}
function parseConfigValue(raw, existingValue) {
  if (raw === "null")
    return null;
  if (raw === "true")
    return true;
  if (raw === "false")
    return false;
  if (typeof existingValue === "string")
    return raw;
  if (existingValue === null || existingValue === undefined)
    return raw;
  const num = Number(raw);
  if (!Number.isNaN(num) && raw.trim() !== "")
    return num;
  return raw;
}

