// src/services/deploy-uninstall-service.ts
var TERMINAL_STATUSES4 = new Set([
  "SuccessfulUninstall",
  "FailedUninstall"
]);
var fail4 = (reason, message, instructions, exitCode = 1) => ({
  ok: false,
  reason,
  message,
  instructions,
  exitCode
});
async function uninstallDeploymentAsync(deploymentName, options = {}) {
  const [authError, auth] = await catchError2(getSolutionAuthContext({
    tenant: options.tenant,
    loginValidity: options.loginValidity,
    envFilePath: options.envFilePath
  }));
  if (authError) {
    return fail4("auth_failed", authError.message, authError.message);
  }
  const api = new PipelinesApi(new Configuration({
    basePath: auth.basePath,
    accessToken: auth.accessToken
  }));
  const [uninstallError, uninstallResult] = await catchError2(api.pipelinesUninstall({ deploymentName }));
  if (uninstallError) {
    const { message, details } = await extractErrorDetails(uninstallError);
    return fail4("uninstall_request_failed", message, `Check deployment name matches an existing deployment. Details: ${details}`);
  }
  if (uninstallResult.complete) {
    return {
      ok: true,
      status: "Uninstall completed immediately",
      deploymentName
    };
  }
  const instanceId = uninstallResult.instanceId;
  if (!instanceId) {
    return {
      ok: true,
      status: "Uninstall scheduled",
      deploymentName,
      scheduled: uninstallResult.scheduled
    };
  }
  const pollResult = await pollUntil({
    fn: () => api.pipelinesGetDeploymentInstanceStatus({ instanceId }),
    until: (result) => TERMINAL_STATUSES4.has(result.status),
    getStatus: (result) => result.status,
    label: `uninstall ${deploymentName}`,
    logPrefix: "uninstall",
    timeoutMs: (options.timeout ?? 360) * 1000,
    intervalMs: options.pollInterval ?? 5000,
    signal: options.signal
  });
  if (pollResult.outcome !== PollOutcome.Completed || !pollResult.data) {
    const { reason, message, exitCode } = mapPollFailure(pollResult, "Uninstall");
    return fail4(reason, message, "Uninstall may still be in progress.", exitCode);
  }
  const finalStatus = pollResult.data;
  if (finalStatus.status !== "SuccessfulUninstall") {
    const errors2 = coerceWorkflowErrorMessages(finalStatus.errorMessage).map((e) => e.errorMessage).join(", ") || "Unknown error";
    return fail4("uninstall_failed", `Uninstall failed with status: ${finalStatus.status}`, errors2);
  }
  return {
    ok: true,
    status: finalStatus.status,
    deploymentName,
    instanceId
  };
}

