var SOLUTION_DOWNLOAD_EXAMPLES = [
  {
    Description: "Download a Studio Web solution as a .uis archive and extract it",
    Command: "uip solution download a1b2c3d4-0000-0000-0000-000000000001 -d ./downloads --extract",
    Output: {
      Code: "SolutionDownload",
      Data: {
        Status: "Solution exported successfully",
        SolutionId: "a1b2c3d4-0000-0000-0000-000000000001",
        Output: "./downloads/a1b2c3d4-0000-0000-0000-000000000001.uis",
        ExtractedTo: "./downloads/a1b2c3d4-0000-0000-0000-000000000001"
      }
    }
  }
];
function registerDownloadCommand(program2) {
  const download = program2.command("download").description("Download/export a solution from Studio Web").argument("<solution-id>", "Solution UUID to export").option("-d, --destination <dir>", "Destination directory for the downloaded file", ".").option("-n, --name <name>", "Output filename (without extension). Existing files are overwritten; --extract uses this name for the directory").option("--extract", "Extract the downloaded .uis zip into a directory", false).examples(SOLUTION_DOWNLOAD_EXAMPLES);
  useStudioWebAuth(download, { requireOrganizationId: true }).trackedAction(processContext, async (solutionId, options, command) => {
    const [error] = await catchError2(downloadSolution(solutionId, options, command));
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to download solution",
        Instructions: error.message
      });
      processContext.exit(1);
    }
  });
}
async function downloadSolution(solutionId, options, command) {
  const fs7 = getFileSystem();
  const filename = getOutputFilename(options.name ?? solutionId);
  const auth = getStudioWebAuthWithOrganizationId(command);
  const organizationPathSegment = encodeURIComponent(auth.organizationId);
  const url = `${auth.baseUrl}/${organizationPathSegment}/studio_/backend/api/Solution/${encodeURIComponent(solutionId)}/Export`;
  const response = await fetch(url, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${auth.accessToken}`
    }
  });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Studio Web API returned ${response.status}: ${text}`);
  }
  const outputDir = fs7.path.resolve(options.destination);
  await fs7.mkdir(outputDir);
  const outputPath = fs7.path.join(outputDir, filename);
  const arrayBuffer = await response.arrayBuffer();
  await fs7.writeFile(outputPath, new Uint8Array(arrayBuffer));
  logger.info(`Downloaded solution to ${outputPath}`);
  const extractedTo = options.extract ? fs7.path.join(outputDir, filename.replace(/\.uis$/, "")) : undefined;
  if (extractedTo) {
    await extractArchive(outputPath, extractedTo);
    logger.info(`Extracted to ${extractedTo}`);
  }
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: "SolutionDownload",
    Data: {
      Status: "Solution exported successfully",
      SolutionId: solutionId,
      Output: outputPath,
      ...extractedTo ? { ExtractedTo: extractedTo } : {}
    }
  });
}
function getOutputFilename(name) {
  validatePlainFilename(name);
  return name.endsWith(".uis") ? name : `${name}.uis`;
}
function validatePlainFilename(name) {
  if (name === "" || name === "." || name.includes("..") || name.includes("/") || name.includes("\\")) {
    throw new Error("Output filename must be a plain filename without path separators or '..'.");
  }
}

