// src/services/solution-init-service.ts
init_src();
var AGENTS_FILENAME = "AGENTS.md";
var CLAUDE_FILENAME = "CLAUDE.md";

class SolutionInitError extends Error {
  stage;
  constructor(stage, cause) {
    super(cause instanceof Error ? cause.message : String(cause), {
      cause
    });
    this.stage = stage;
    this.name = "SolutionInitError";
  }
}
async function solutionInitAsync(solutionName, options = {}) {
  const fs7 = getFileSystem();
  const base = fs7.path.basename(solutionName);
  const hasExtension = base.lastIndexOf(".") > 0;
  const nameWithoutExt = hasExtension ? base.slice(0, base.lastIndexOf(".")) : base;
  const fileName = hasExtension ? base : `${base}.uipx`;
  const parentDir = fs7.path.resolve(options.cwd ?? ".", fs7.path.dirname(solutionName), nameWithoutExt);
  const [mkdirError] = await catchError2(fs7.mkdir(parentDir));
  if (mkdirError) {
    throw new SolutionInitError("directory", mkdirError);
  }
  let agentsPath;
  let claudePath;
  if (options.briefingContent !== undefined) {
    agentsPath = fs7.path.join(parentDir, AGENTS_FILENAME);
    claudePath = fs7.path.join(parentDir, CLAUDE_FILENAME);
    const [agentsError] = await catchError2(fs7.writeFile(agentsPath, options.briefingContent));
    if (agentsError) {
      throw new SolutionInitError("briefing", agentsError);
    }
    const [claudeError] = await catchError2(fs7.writeFile(claudePath, options.briefingContent));
    if (claudeError) {
      throw new SolutionInitError("briefing", claudeError);
    }
  }
  const filePath = fs7.path.join(parentDir, fileName);
  const solution = {
    DocVersion: "1.0.0",
    StudioMinVersion: "2025.10.0",
    SolutionId: crypto.randomUUID(),
    Projects: []
  };
  const [manifestError] = await catchError2(fs7.writeFile(filePath, `${JSON.stringify(solution, null, 2)}
`));
  if (manifestError) {
    throw new SolutionInitError("manifest", manifestError);
  }
  return {
    solutionFile: filePath,
    solutionDir: parentDir,
    solutionName: nameWithoutExt,
    agentsPath,
    claudePath
  };
}

