class SolutionUpdateCommandHandler {
  async handleAsync(command, cancellationToken) {
    const { model } = command;
    this.logger.info(`Updating name for solution ${command.context} from '${model.oldSolutionName}' to '${model.solutionName}'`);
    const solution = await command.context.loadAsync(cancellationToken);
    const processResources = solution.resources.filter(isProcessArtefact);
    if (processResources.length === 0)
      return void this.logger.warn(`No process artefact resources found in solution ${command.context}`);
    let save = false;
    for (const resource of processResources)
      save = changePackageName(resource, model.solutionName, resource.name, model.oldSolutionName) || save;
    if (save) {
      await command.context.saveChangesAsync(cancellationToken);
      this.logger.info(`The name for solution ${command.context} was updated`);
    } else
      this.logger.info(`No changes were made to solution ${command.context}`);
  }
  constructor(loggerFactory) {
    this.logger = loggerFactory.create("SolutionUpdateCommandHandler");
  }
}

