    const solution = await command.context.loadAsync(cancellationToken);
    const projectResources = solution.resources.filter((x2) => x2.projectKey === command.projectKey);
    if (projectResources.length === 0)
      return void this.logger.warn("Project with key {projectKey} not found in solution", {
        projectKey: command.projectKey,
        context: command.context
      });
    const newProjectName = command.projectDetails.name.trim();
    const projectDescription = command.projectDetails.description;
    const solutionName = command.projectDetails.solutionName;
    const duplicateProject = solution.resources.find((r) => r.isArtefactResource && r.projectKey !== command.projectKey && r.name.toLowerCase() === newProjectName.toLowerCase());
    if (duplicateProject) {
      this.logger.error("Project name already exists");
      throw new BadRequestException(ErrorCodes.Resources.DuplicateResourceName, "Project name already exists");
    }
    const existingConflictResource = solution.resources.find((r) => !r.isArtefactResource && r.name.toLowerCase() === newProjectName.toLowerCase() && projectResources.some((pr) => r.kind.toLowerCase() === pr.kind.toLowerCase()));
