class ProjectConfigurationService {
  async getDefaultConfigurationAsync(cancellationToken) {
    const projectsConfiguration = this.projectConfigurationReader.getAll();
    const language = this.getCurrentLanguage();
    const entries = Object.entries(projectsConfiguration);
    const results = {};
    for (const [projectType, config] of entries) {
      const supportedResources = await this.projectResourcesDescriptorFactory.createAsync(projectType, language, cancellationToken);
      results[projectType] = {
        ...config,
        supportedResources
      };
    }
    return results;
  }
  getCurrentLanguage() {
    if ("u" > typeof navigator && navigator.language)
      return navigator.language;
    if ("u" > typeof process && process.env?.["LANG"])
      return process.env["LANG"].split(".")[0] ?? "en";
    return "en";
  }
  constructor(projectConfigurationReader, projectResourcesDescriptorFactory) {
    this.projectConfigurationReader = projectConfigurationReader;
    this.projectResourcesDescriptorFactory = projectResourcesDescriptorFactory;
  }
}
