function csharpGuidFromString(input) {
  const b = createHash("sha256").update(input, "utf8").digest().subarray(0, 16);
  const h = (n) => n.toString(16).padStart(2, "0");
  return [
    h(b[3]) + h(b[2]) + h(b[1]) + h(b[0]),
    h(b[5]) + h(b[4]),
    h(b[7]) + h(b[6]),
    h(b[8]) + h(b[9]),
    h(b[10]) + h(b[11]) + h(b[12]) + h(b[13]) + h(b[14]) + h(b[15])
  ].join("-");
}
