async function findProjectFile(projectDir) {
  const fs9 = getFileSystem();
  const uiprojPath = fs9.path.join(projectDir, "project.uiproj");
  const jsonProjPath = fs9.path.join(projectDir, "project.json");
  const uipathJsonPath = fs9.path.join(projectDir, "uipath.json");
  if (await fs9.exists(uiprojPath)) {
    return [
      null,
      {
        filePath: uiprojPath,
        fileName: "project.uiproj",
        useProjectJson: false
      }
    ];
  }
  if (await fs9.exists(jsonProjPath)) {
    return [
      null,
      {
        filePath: jsonProjPath,
        fileName: "project.json",
        useProjectJson: true
      }
    ];
  }
  if (await fs9.exists(uipathJsonPath)) {
    return [
      null,
      {
        filePath: uipathJsonPath,
        fileName: "uipath.json",
        useProjectJson: false
      }
    ];
  }
  return [
    new Error(`No project file found in ${projectDir}. Expected project.uiproj, project.json, or uipath.json (Functions).`),
    null
  ];
}
async function readProjectFile(filePath, useProjectJson) {
  const fs9 = getFileSystem();
  const [readError, rawContent] = await catchError2(fs9.readFile(filePath, "utf-8"));
  if (readError || !rawContent) {
    return [readError ?? new Error("Unable to read project file"), null];
  }
  const [parseError, content] = catchError2(() => JSON.parse(rawContent));
  if (parseError) {
    return [
      new Error(`Invalid JSON in project file: ${parseError.message}`),
      null
    ];
  }
  const projectType = useProjectJson ? content.designOptions?.outputType ?? content.ProjectType : content.ProjectType;
  if (!projectType) {
    if (content.functions && typeof content.functions === "object") {
      return [
        null,
        {
          content,
          projectType: normalizeProjectType("Function" /* Function */)
        }
      ];
    }
    return [new Error(`ProjectType not found in ${filePath}`), null];
  }
  return [null, { content, projectType: normalizeProjectType(projectType) }];
}
async function readSolutionFile(filePath) {
  const fs9 = getFileSystem();
  const [readError, rawContent] = await catchError2(fs9.readFile(filePath, "utf-8"));
  if (readError || !rawContent) {
    return [readError ?? new Error("Unable to read solution file"), null];
  }
  const [parseError, solution] = catchError2(() => JSON.parse(rawContent));
  if (parseError) {
    return [
      new Error(`Invalid JSON in solution file: ${parseError.message}`),
      null
    ];
  }
  return [null, { solution, rawContent }];
}
async function resolveSolutionFilePath(solutionFileOption, searchStartDir) {
  const fs9 = getFileSystem();
  if (solutionFileOption) {
    const resolved = fs9.path.resolve(fs9.env.cwd(), solutionFileOption);
    const exists = await fs9.exists(resolved);
    if (!exists) {
      return [new Error(`Solution file not found: ${resolved}`), null];
    }
    return [null, resolved];
  }
  const [findError, found] = await catchError2(findSolutionFile2(searchStartDir));
  if (findError) {
    return [findError, null];
  }
  return [null, found];
}
async function writeSolutionFile(filePath, solution) {
  const fs9 = getFileSystem();
  const [writeError] = await catchError2(fs9.writeFile(filePath, `${JSON.stringify(solution, null, 2)}
`));
  return writeError;
}
async function restoreSolutionFile(filePath, rawContent) {
  const fs9 = getFileSystem();
  const [writeError] = await catchError2(fs9.writeFile(filePath, rawContent));
  return writeError;
}
async function createProjectInSolutionBuilder(solutionDir, projectId, projectName, projectType) {
  const [servicesError, services2] = await catchError2(createResourceBuilderServices());
  if (servicesError) {
    return servicesError;
  }
  const [builderError, solutionBuilder] = await catchError2(services2.getSolutionBuilder(solutionDir));
  if (builderError) {
    return builderError;
  }
  const [createError] = await catchError2(solutionBuilder.createProjectAsync({
    projectKey: projectId,
    name: projectName,
    type: projectType
  }));
  await catchError2(solutionBuilder.disposeAsync());
  return createError;
}

