    solution.Projects.push({
      Type: parsedProject.projectType,
      ProjectRelativePath: projectRelativePath,
      Id: projectId
    });
    const writeError = await writeSolutionFile(resolvedSolutionFile, solution);
    if (writeError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to add project to solution",
        Instructions: writeError.message
      });
      processContext.exit(1);
      return;
    }
    const createError = await createProjectInSolutionBuilder(solutionDir, projectId, projectName, parsedProject.projectType);
    if (createError) {
      const restoreError = await restoreSolutionFile(resolvedSolutionFile, originalSolutionContent);
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to add project to solution",
        Instructions: restoreError ? `${createError.message}
Rollback failed: ${restoreError.message}` : createError.message
      });
      processContext.exit(1);
      return;
    }
    const syncResult = await syncResourcesFromBindings(solutionDir, [resolvedProjectPath]);
    if (syncResult.warnings.length > 0) {
      for (const warning of syncResult.warnings) {
        logger.warn(warning);
      }
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "ProjectAdd",
      Data: {
        Status: "Added successfully",
        Project: projectRelativePath,
        Solution: resolvedSolutionFile
      }
    });
