// src/commands/project.ts
async function findSolutionFile2(startDir) {
  const fs9 = getFileSystem();
  let dir = startDir;
  while (true) {
    const entries = await fs9.readdir(dir);
    const files = entries.filter((f) => f.endsWith(".uipx"));
    if (files.length === 1) {
      return fs9.path.join(dir, files[0]);
    }
    if (files.length > 1) {
      throw new Error(`Multiple .uipx files found in ${dir}. Please specify which solution file to use.`);
    }
    const parent = fs9.path.dirname(dir);
    if (parent === dir) {
      throw new Error(`No .uipx solution file found (searched from ${startDir} to filesystem root)`);
    }
    dir = parent;
  }
}
var registerProjectCommand = (program3) => {
  const project = program3.command("project").description("Manage projects within a UiPath solution (.uipx). Add, import, or remove automation projects (workflows, test cases, libraries) from the solution manifest.");
  registerProjectAddCommand(project);
  registerProjectImportCommand(project);
  registerProjectListCommand(project);
  registerProjectPublishCommand(project);
  registerProjectRemoveCommand(project);
  registerProjectResyncCommand(project);
};

