async function assertSolutionManifest(dir) {
  const fs9 = getFileSystem();
  const entries = await fs9.readdir(dir);
  const hasManifest = entries.some((f) => f.endsWith(".uipx"));
  if (!hasManifest) {
    throw new Error(`${dir} is not a UiPath solution (no .uipx manifest found). Run 'uip solution init' first, or pass --solution-folder pointing at an existing solution.`);
  }
}

