async function getRemoteConfiguration(services2, resourceKey, includeDependencies) {
  const reference = await findRemoteReferenceByKey(services2, resourceKey);
  if (!reference) {
    throw new Error(`Resource '${resourceKey}' was not found in the solution or in the resource catalog`);
  }
  const importer = services2.container.resolve(Tokens.IImportResourceHelper);
  const payload = await importer.exportResourceAsync(reference);
  const definitions = payload.resourceDefinitions ?? [];
  const primary = definitions.find((d) => d.key === resourceKey) ?? definitions[0];
  if (!primary) {
    throw new Error(`FPS export for '${resourceKey}' returned no resource definitions`);
  }
  if (!includeDependencies) {
    return mapDefinitionToConfiguration(primary);
  }
  const all = {
    resources: definitions.map((d) => ({
      ...mapDefinitionToConfiguration(d),
      name: d.name ?? "",
      kind: d.kind ?? "",
      dependencies: (d.dependencies ?? []).map((dep) => ({
        kind: dep.kind ?? "",
        name: dep.name ?? ""
      }))
    }))
  };
  return all;
}
function mapDefinitionToConfiguration(def) {
  return {
    key: def.key ?? "",
    spec: def.spec ?? {},
    locks: def.locks ?? [],
    apiVersion: def.apiVersion,
    isOverridable: def.isOverridable
  };
}
async function refreshArtefactSpecAsync(builder, data, includeDeps) {
  const [loadError, solution] = await catchError2(builder.context.loadAsync());
  if (loadError || !solution) {
    return;
  }
  const configs = includeDeps ? data.resources ?? [] : [data];
  for (const config of configs) {
    if (!config?.key) {
      continue;
    }
    const resource = solution.resources.find((r) => r.key === config.key);
    if (!resource?.projectKey) {
      continue;
    }
    config.spec = await applyEntryPointEnhancementAsync(builder.context, resource, config.spec ?? {});
  }
}
async function findRemoteReferenceByKey(services2, resourceKey) {
  const rcs = services2.container.resolve(Tokens.IResourceCatalogClientProxy);
  let pageCursor;
  do {
    const result = await rcs.searchFolderEntities({
      pageSize: 100,
      pageCursor
    });
    for (const item of result.items ?? []) {
      if (item.entityKey === resourceKey) {
        return {
          kind: item.entityType ?? "",
          type: item.entitySubType ?? undefined,
          key: item.entityKey ?? resourceKey,
          name: item.entityName ?? undefined,
          folder: item.fullyQualifiedName ? {
            fullyQualifiedName: item.fullyQualifiedName,
            folderKey: item.folderKey ?? undefined
          } : undefined
        };
      }
    }
    pageCursor = result.nextPage ?? undefined;
  } while (pageCursor);
  return null;
}

