var registerResourceListCommand = (resource) => {
  resource.command("list").description("List resources in the solution and/or available in Orchestrator. " + "Shows local solution resources, remote Orchestrator resources, or both.").option("--solution-folder <path>", "Path to the solution root folder (defaults to current directory)").option("--kind <kind>", "Filter by resource kind (e.g. Queue, Asset, Bucket, Process, Connection, App, Index, Trigger). Any kind RCS indexes is accepted.").option("--search <term>", "Filter resources by name").option("--source <source>", "Resource source: all, local, or remote (default: all)", "all").option("--login-validity <minutes>", "Minimum minutes before token expiration to trigger a refresh (default: 10)", parseInt, 10).trackedAction(processContext, async (options) => {
    const solutionPath = options.solutionFolder ?? ".";
    const fs9 = getFileSystem();
    const resolvedPath = fs9.path.resolve(fs9.env.cwd(), solutionPath);
    const exists = await fs9.exists(resolvedPath);
    if (!exists) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to list resources",
        Instructions: `Solution directory not found: ${resolvedPath}`
      });
      processContext.exit(1);
      return;
    }
    const source = options.source.toLowerCase();
    if (!["all", "local", "remote"].includes(source)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Invalid --source value",
        Instructions: "Use one of: all, local, remote"
      });
      processContext.exit(1);
      return;
    }
    const normalizedKind = options.kind;
    const [authError] = await catchError2(getSolutionAuthContext({
      loginValidity: options.loginValidity
    }));
    if (authError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to authenticate",
        Instructions: await extractErrorMessage(authError)
      });
      processContext.exit(1);
      return;
    }
    const [servicesError, services2] = await catchError2(createResourceBuilderServices());
    if (servicesError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to initialize resource builder",
        Instructions: servicesError.message
      });
      processContext.exit(1);
      return;
    }
    const [builderError, builder] = await catchError2(services2.getSolutionBuilder(resolvedPath, true));
    if (builderError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to load solution",
        Instructions: builderError.message
      });
      processContext.exit(1);
      return;
    }
    const [listError, data] = await catchError2(listResources(builder, services2, source, normalizedKind, options.search));
    await builder.disposeAsync();
    if (listError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to list resources",
        Instructions: listError.message
      });
      processContext.exit(1);
      return;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "ResourceList",
      Data: data
    });
  });
};
async function listResources(builder, services2, source, kind, search3) {
  const includeLocal = source === "local" || source === "all";
  const includeRemote = source === "remote" || source === "all";
  if (kind) {
    return querySingleKind(builder, kind, search3, includeLocal, includeRemote);
  }
  const all = [];
  if (includeLocal) {
    all.push(...await listLocalResources(builder, undefined, search3));
  }
  if (includeRemote) {
    const remote = await listAllRemoteResources(services2, search3);
    const localKeys = new Set(all.map((e) => `${e.Kind}:${e.Name}`.toLowerCase()));
    const uniqueRemote = remote.filter((r) => !localKeys.has(`${r.Kind}:${r.Name}`.toLowerCase()));
    all.push(...uniqueRemote);
  }
  return all;
}
async function listAllRemoteResources(services2, search3) {
  const rcs = services2.container.resolve(Tokens.IResourceCatalogClientProxy);
  const entries = [];
  let pageCursor;
  do {
    const [err2, result] = await catchError2(rcs.searchFolderEntities({
      name: search3,
      pageSize: 100,
      pageCursor
    }));
    if (err2) {
      logger.warn(`Failed to search remote resources: ${err2.message}`);
      return entries;
    }
    for (const item of result.items ?? []) {
      entries.push({
        Source: "Remote",
        Key: item.entityKey ?? "",
        Name: item.entityName ?? "",
        Kind: item.entityType ?? "",
        Type: item.entitySubType ?? undefined,
        Folder: item.fullyQualifiedName,
        FolderKey: item.folderKey
      });
    }
    pageCursor = result.nextPage ?? undefined;
  } while (pageCursor);
  return entries;
}
async function listLocalResources(builder, kind, search3) {
  const solution = await builder.context.loadAsync();
  let resources = solution.resources ?? [];
  if (kind) {
    resources = resources.filter((r) => r.kind?.toLowerCase() === kind.toLowerCase());
  }
  if (search3) {
    const term = search3.toLowerCase();
    resources = resources.filter((r) => r.name?.toLowerCase().includes(term));
  }
  return resources.map((r) => ({
    Source: "Local",
    Key: r.key ?? "",
    Name: r.name ?? "",
    Kind: r.kind ?? "",
    Type: r.type,
    Folder: r.folders?.[0]?.fullyQualifiedName
  }));
}
async function querySingleKind(builder, kind, search3, includeLocal, includeRemote) {
  const entries = [];
  let pageCursor;
  do {
    const result = await builder.searchResourcesAsync(kind, undefined, search3, pageCursor, 100, undefined, includeLocal);
    if (includeLocal) {
      for (const r of result.solutionResources ?? []) {
        entries.push({
          Source: "Local",
          Key: r.key ?? "",
          Name: r.name ?? "",
          Kind: r.kind ?? "",
          Type: r.type,
          Folder: r.folders?.[0]?.fullyQualifiedName
        });
      }
    }
    if (includeRemote) {
      for (const folder of result.availableResources ?? []) {
        for (const r of folder.resources ?? []) {
          entries.push({
            Source: "Remote",
            Key: r.key,
            Name: r.name,
            Kind: r.kind,
            Type: r.type,
            Folder: folder.fullyQualifiedName,
            FolderKey: folder.key
          });
        }
      }
    }
    pageCursor = result.nextPage;
  } while (pageCursor);
  if (includeLocal && includeRemote) {
    const localKeys = new Set(entries.filter((e) => e.Source === "Local").map((e) => `${e.Kind}:${e.Name}`.toLowerCase()));
    return entries.filter((e) => e.Source === "Local" || !localKeys.has(`${e.Kind}:${e.Name}`.toLowerCase()));
  }
  return entries;
}

// src/services/resource-refresh-service.ts
init_src();
async function resourceRefreshAsync(solutionPath = ".", options = {}) {
  const fs9 = getFileSystem();
  const resolvedPath = fs9.path.resolve(fs9.env.cwd(), solutionPath);
  if (!await fs9.exists(resolvedPath)) {
    return {
      ok: false,
      reason: "solution_not_found",
      message: `Solution directory not found: ${resolvedPath}`
    };
  }
  const [manifestError] = await catchError2(assertSolutionManifest(resolvedPath));
  if (manifestError) {
    return {
      ok: false,
      reason: "not_a_solution",
      message: manifestError.message
    };
  }
  const [authError] = await catchError2(getSolutionAuthContext({
    loginValidity: options.loginValidity,
    envFilePath: options.envFilePath
  }));
  if (authError) {
    return {
      ok: false,
      reason: "auth_failed",
      message: await extractErrorMessage(authError)
    };
  }
  const [syncError, result] = await catchError2(syncResourcesFromBindings(resolvedPath));
  if (syncError) {
    return {
      ok: false,
      reason: "sync_failed",
      message: syncError.message
    };
  }
  return {
    ok: true,
    created: result.created,
    imported: result.imported,
    skipped: result.skipped,
    warnings: result.warnings
  };
}

