init_src();
var GUID_REGEX4 = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
var RESOURCE_REMOVE_EXAMPLES = [
  {
    Description: "Remove a resource by its solution key",
    Command: "uip solution resources remove 8f3a1b2c-1234-4abc-9def-0123456789ab",
    Output: {
      Code: "ResourceRemoved",
      Data: {
        Key: "8f3a1b2c-1234-4abc-9def-0123456789ab",
        Kind: "queue",
        Name: "InvoiceQueue",
        Folder: "solution_folder"
      }
    }
  }
];
var registerResourceRemoveCommand = (resource) => {
  resource.command("remove").description("Remove a resource from the solution by its key. Use 'uip solution resources list' " + "or 'uip solution resources get' to discover the key first. " + "Purely local — no auth required, doesn't touch any bindings_v2.json.").argument("<resource-key>", "Solution resource key (GUID)").option("--solution-folder <path>", "Path to the solution root folder (defaults to current directory)").examples(RESOURCE_REMOVE_EXAMPLES).trackedAction(processContext, async (resourceKey, options) => {
    if (!resourceKey || resourceKey.trim().length === 0) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Missing required argument <resource-key>",
        Instructions: "Pass the solution resource key as a positional argument. Use 'uip solution resources list' to discover keys."
      });
      processContext.exit(1);
      return;
    }
    if (!GUID_REGEX4.test(resourceKey)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "<resource-key> must be a GUID",
        Instructions: "Resource keys are 8-4-4-4-12 hex GUIDs. Use 'uip solution resources list' to find a valid key."
      });
      processContext.exit(1);
      return;
    }
    const fs9 = getFileSystem();
    const resolvedPath = fs9.path.resolve(fs9.env.cwd(), options.solutionFolder ?? ".");
    if (!await fs9.exists(resolvedPath)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to remove resource",
        Instructions: `Solution directory not found: ${resolvedPath}`
      });
      processContext.exit(1);
      return;
    }
    const [manifestError] = await catchError2(assertSolutionManifest(resolvedPath));
    if (manifestError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to remove resource",
        Instructions: manifestError.message
      });
      processContext.exit(1);
      return;
    }
    const [servicesError, services2] = await catchError2(createResourceBuilderServices());
    if (servicesError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to initialize resource builder",
        Instructions: servicesError.message
      });
      processContext.exit(1);
      return;
    }
    const [builderError, builder] = await catchError2(services2.getSolutionBuilder(resolvedPath));
    if (builderError) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to load solution",
        Instructions: builderError.message
      });
      processContext.exit(1);
      return;
    }
    let removeSucceeded = false;
    try {
      const solution = await builder.context.loadAsync();
      const normalizedKey = resourceKey.toLowerCase();
      const target = solution.resources.find((r) => r.key.toLowerCase() === normalizedKey);
      if (!target) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: "Resource not found in solution",
          Instructions: `No resource with key ${resourceKey}. Use 'uip solution resources list' to see available keys.`
        });
        processContext.exit(1);
        return;
      }
      const captured = {
        Key: target.key,
        Kind: target.kind,
        Name: target.name,
        Folder: target.folders?.[0]?.fullyQualifiedName ?? null
      };
      const [deleteError] = await catchError2(builder.deleteSolutionResourceAsync(target.key));
      if (deleteError) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: "Failed to remove resource",
          Instructions: deleteError.message
        });
        processContext.exit(1);
        return;
      }
      removeSucceeded = true;
      OutputFormatter.success({
        Result: RESULTS.Success,
        Code: "ResourceRemoved",
        Data: captured
      });
    } finally {
      const [disposeError] = await catchError2(builder.disposeAsync());
      if (disposeError) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: removeSucceeded ? "Resource mutation completed but the solution could not be saved" : "Failed to save solution after remove error",
          Instructions: disposeError.message
        });
        processContext.exit(1);
      }
    }
  });
};

